#!/usr/bin/env node

/**
 * Genera archivos CJS bridge (index.js) para los clientes Prisma generados.
 *
 * Prisma v7 genera clientes ESM-only (.ts con import.meta.url).
 * Este script crea wrappers CommonJS que permiten usar los clientes
 * en un proyecto NestJS con module: "commonjs".
 *
 * Ejecutar tras `prisma generate`: npm run prisma:bridge
 */

'use strict';

const fs = require('fs');
const path = require('path');

const BRIDGE_TEMPLATE = `// CJS bridge for Prisma v7 generated ESM client.
// AUTO-GENERATED by scripts/generate-prisma-bridges.js — do not edit manually.
// Regenerate with: npm run prisma:bridge

'use strict';

const runtime = require('@prisma/client/runtime/client');
const fs = require('fs');
const path = require('path');

const classPath = path.join(__dirname, 'internal', 'class.ts');
const classContent = fs.readFileSync(classPath, 'utf8');

const inlineSchemaMatch = classContent.match(/"inlineSchema":\\s*"((?:[^"\\\\\\\\]|\\\\\\\\.)*)"/);
const inlineSchema = inlineSchemaMatch ? JSON.parse('"' + inlineSchemaMatch[1] + '"') : '';

const runtimeDataModelMatch = classContent.match(/config\\.runtimeDataModel\\s*=\\s*JSON\\.parse\\("((?:[^"\\\\\\\\]|\\\\\\\\.)*)"/);
const runtimeDataModel = runtimeDataModelMatch ? JSON.parse(JSON.parse('"' + runtimeDataModelMatch[1] + '"')) : { models: {}, enums: {}, types: {} };

const paramStringsMatch = classContent.match(/strings:\\s*JSON\\.parse\\("((?:[^"\\\\\\\\]|\\\\\\\\.)*)"/);
const paramGraphMatch = classContent.match(/graph:\\s*"((?:[^"\\\\\\\\]|\\\\\\\\.)*)"/);
const parameterizationSchema = {
  strings: paramStringsMatch ? JSON.parse(JSON.parse('"' + paramStringsMatch[1] + '"')) : [],
  graph: paramGraphMatch ? paramGraphMatch[1] : ''
};

const config = {
  previewFeatures: [],
  clientVersion: '7.4.2',
  activeProvider: 'postgresql',
  inlineSchema,
  runtimeDataModel,
  parameterizationSchema,
  compilerWasm: {
    getRuntime: async () => await import('@prisma/client/runtime/query_compiler_fast_bg.postgresql.mjs'),
    getQueryCompilerWasmModule: async () => {
      const { wasm } = await import('@prisma/client/runtime/query_compiler_fast_bg.postgresql.wasm-base64.mjs');
      const { Buffer } = await import('node:buffer');
      const wasmArray = Buffer.from(wasm, 'base64');
      return new WebAssembly.Module(wasmArray);
    },
    importName: './query_compiler_fast_bg.js'
  }
};

const PrismaClient = runtime.getPrismaClient(config);

module.exports = { PrismaClient };
`;

const schemas = [
  path.join(__dirname, '..', 'prisma', 'main', 'generated'),
  path.join(__dirname, '..', 'prisma', 'tenant', 'generated'),
];

for (const dir of schemas) {
  const bridgePath = path.join(dir, 'index.js');

  if (!fs.existsSync(path.join(dir, 'internal', 'class.ts'))) {
    console.warn(`Skipping ${dir}: internal/class.ts not found (run prisma generate first)`);
    continue;
  }

  fs.writeFileSync(bridgePath, BRIDGE_TEMPLATE, 'utf8');
  console.log(`Generated CJS bridge: ${bridgePath}`);
}

console.log('Prisma CJS bridges generated successfully.');
